 * whole megabytes, so half a megabyte still costs one. Uploads are charged and
 * deletions refunded with this same figure.
 */
function chargedMb(sizeBytes: number): number {
  return Math.ceil(sizeBytes / BYTES_PER_MB);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * `organizations.plan` column is only the fallback when no subscription exists.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

