const MB = 1024 * 1024;
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

async function upload(t: any, issueId: any, bytes: number) {
  return attachmentService.addAttachment(t.actors.owner, { orgId: t.org.id, issueId, filename: "f", contentType: "text/plain", sizeBytes: bytes });
