}

describe("storage", () => {
  it("billing matches uploads, delete refunds, recount agrees", async () => {
    const t = await createTenant("s1", "starter");
    const other = await createTenant("s2", "starter");
    const issue = await newIssue(t);
    const oi = await newIssue(other);
    const a = await upload(t, issue.id, Math.round(0.4 * MB));
    const b = await upload(t, issue.id, Math.round(2.5 * MB));
    await upload(other, oi.id, 5 * MB);
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(4);
    const summary = await billingService.getBillingSummary(t.actors.owner, t.org.id);
    expect(summary.checks.find((c) => c.resource === "storageMb")!.used).toBe(4);
    const r = await usageRepo.recomputeUsage(t.org.id);
    expect(r.storageMbUsed).toBe(4);
    await attachmentService.removeAttachment(t.actors.owner, { orgId: t.org.id, attachmentId: a.id });
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(3);
    await expect(attachmentService.removeAttachment(t.actors.owner, { orgId: t.org.id, attachmentId: a.id })).rejects.toMatchObject({ code: "not_found" });
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(3);
    await issueService.archiveIssue?.(t.actors.owner, t.org.id, issue.id).catch((e: any) => console.log("archive", e.message));
    await attachmentService.removeAttachment(t.actors.owner, { orgId: t.org.id, attachmentId: b.id });
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(0);
    expect((await usageRepo.recomputeUsage(t.org.id)).storageMbUsed).toBe(0);
    expect((await usageRepo.recomputeUsage(other.org.id)).storageMbUsed).toBe(5);
  });
  it("trial with storage over free stays", async () => {
    const t = await createTenant("s3", "starter");
    const t2 = await createTenant("s4", "starter");
    for (const x of [t, t2]) {
      await usageRepo.recomputeUsage(x.org.id);
    }
    await usageRepo.incrementUsage(t.org.id, { storageMbUsed: 101 });
    await usageRepo.incrementUsage(t2.org.id, { storageMbUsed: 100 });
    getDb().update(subscriptions).set({ status: "trialing", trialEndsAt: "2020-01-01T00:00:00.000Z" } as any).run();
    const res = await runTrialExpiryJob(new Date());
    console.log(res);
    console.log((await subscriptionRepo.findSubscription(t.org.id))!.plan, (await subscriptionRepo.findSubscription(t2.org.id))!.plan);
  });
});
EOF
